For cosmetic and topical use only. Not for injection or internal use.','["https://rtsnxmatvbabdylsnuuh.supabase.co/storage/v1/object/public/menu-images/1769340207120-dt4u1iya59p.png"]'::jsonb,1,'active','{"category":"topicals-and-serums","srcId":"f05ddbde-cf23-4c37-b5d9-51b62d4ac600","purity":"99.00","storage":"Store at -20°C"}'::jsonb);
