INSERT INTO products (id,"tenantId",sku,slug,name,"priceCents",currency,description,images,stock,status,metadata) VALUES ('hpglow-glow-sculpt-duo-tirzepatide-15mg-ghk-cu-50mg','hpglow','GLOWSCULPTDUOTIR','glow-sculpt-duo-tirzepatide-15mg-ghk-cu-50mg','Glow Sculpt Duo (Tirzepatide 15mg & GHK-CU 50mg)',369800,'PHP','The 𝗚𝗹𝗼𝘄 𝗦𝗰𝘂𝗹𝗽𝘁 𝗕𝘂𝗻𝗱𝗹𝗲 combines two peptides commonly used in wellness and metabolic support protocols.

