INSERT INTO products (id,"tenantId",sku,slug,name,"priceCents",currency,description,images,stock,status,metadata) VALUES ('hpglow-snap-8-topical-use-only','hpglow','SNAP8TOPICALUSEO','snap-8-topical-use-only','Snap-8 (Topical Use Only)',99900,'PHP','𝗦𝗻𝗮𝗽-𝟴 is a synthetic peptide that 𝗺𝗶𝗺𝗶𝗰𝘀 𝘁𝗵𝗲 𝗲𝗳𝗳𝗲𝗰𝘁𝘀 𝗼𝗳 𝗕𝗼𝘁𝗼𝘅. It is used to 𝗿𝗲𝗱𝘂𝗰𝗲 𝘁𝗵𝗲 𝗮𝗽𝗽𝗲𝗮𝗿𝗮𝗻𝗰𝗲 𝗼𝗳 𝘄𝗿𝗶𝗻𝗸𝗹𝗲𝘀 𝗮𝗻𝗱 𝗲𝘅𝗽𝗿𝗲𝘀𝘀𝗶𝗼𝗻 𝗹𝗶𝗻𝗲𝘀 by inhibiting acetylcholine, which relaxes the facial muscles and reduces the signals sent to those muscles by neurotransmitters. Snap-8 also 𝗽𝗿𝗼𝗺𝗼𝘁𝗲𝘀 𝗰𝗼𝗹𝗹𝗮𝗴𝗲𝗻 𝘀𝘆𝗻𝘁𝗵𝗲𝘀𝗶𝘀, 𝗶𝗺𝗽𝗿𝗼𝘃𝗲𝘀 𝘀𝗸𝗶𝗻 𝗲𝗹𝗮𝘀𝘁𝗶𝗰𝗶𝘁𝘆, 𝗮𝗻𝗱 𝗵𝘆𝗱𝗿𝗮𝘁𝗲𝘀 𝗮𝗻𝗱 𝗻𝗼𝘂𝗿𝗶𝘀𝗵𝗲𝘀 𝘁𝗵𝗲 𝘀𝗸𝗶𝗻.','["https://rtsnxmatvbabdylsnuuh.supabase.co/storage/v1/object/public/menu-images/1769338726217-aa09yk2itk.png"]'::jsonb,0,'draft','{"category":"topicals-and-serums","srcId":"4f6bad50-f544-4006-ba84-ba444681cb6f","purity":"99.00","storage":"Store at -20°C (unreconstituted)"}'::jsonb);
