INSERT INTO products (id,"tenantId",sku,slug,name,"priceCents",currency,description,images,stock,status,metadata) VALUES ('hpglow-glow-sculpt-duo-tirzepatide-30mg-ghk-cu-100mg-free-shipping-','hpglow','GLOWSCULPTDUOTIR-2','glow-sculpt-duo-tirzepatide-30mg-ghk-cu-100mg-free-shipping-','Glow Sculpt Duo (Tirzepatide 30mg & GHK-CU 100mg) - FREE SHIPPING NATIONWIDE',554800,'PHP','The 𝗚𝗹𝗼𝘄 𝗦𝗰𝘂𝗹𝗽𝘁 𝗕𝘂𝗻𝗱𝗹𝗲 combines two peptides commonly used in wellness and metabolic support protocols. 𝗧𝗶𝗿𝘇𝗲𝗽𝗮𝘁𝗶𝗱𝗲 works on GLP-1 and GIP receptors, helping regulate appetite, slow gastric emptying, and support blood sugar control. 𝗚𝗛𝗞-𝗖𝘂 (Copper Peptide) is known for its role in skin repair and regeneration, supporting collagen production, tissue healing, and overall skin health.','["https://rtsnxmatvbabdylsnuuh.supabase.co/storage/v1/object/public/menu-images/1778740277386-n2x6lgeg3n.png"]'::jsonb,4,'active','{"category":"all","srcId":"44650557-730e-4a51-9a35-0c08506cda84","purity":"99.00","storage":"Store at -20°C","featured":true,"freeShipping":true,"discountEnabled":true,"discountPrice":4799}'::jsonb);
INSERT INTO products (id,"tenantId",sku,slug,name,"priceCents",currency,description,images,stock,status,metadata) VALUES ('hpglow-ara-290','hpglow','ARA290','ara-290','ARA-290',189900,'PHP','𝗔𝗥𝗔-𝟮𝟵𝟬 (aka Cibinetide) is a synthetic peptide derived from erythropoietin (EPO) designed to activate the innate repair receptor (IRR) and produce 𝗮𝗻𝘁𝗶-𝗶𝗻𝗳𝗹𝗮𝗺𝗺𝗮𝘁𝗼𝗿𝘆, 𝗻𝗲𝘂𝗿𝗼𝗽𝗿𝗼𝘁𝗲𝗰𝘁𝗶𝘃𝗲, 𝗮𝗻𝗱 𝘁𝗶𝘀𝘀𝘂𝗲-𝗿𝗲𝗽𝗮𝗶𝗿 𝗲𝗳𝗳𝗲𝗰𝘁𝘀 without EPO’s red bood-cell-stimulating or pro-thrombotic actions. This peptide has been studied for its potential to 𝗵𝗲𝗹𝗽 𝗿𝗲𝗹𝗶𝗲𝘃𝗲 𝗻𝗲𝘂𝗿𝗼𝗽𝗮𝘁𝗵𝗶𝗰 𝗽𝗮𝗶𝗻, particularly small-fiber neuropathy, while 𝘀𝘂𝗽𝗽𝗼𝗿𝘁𝗶𝗻𝗴 𝗻𝗲𝗿𝘃𝗲 𝗿𝗲𝗽𝗮𝗶𝗿 𝗮𝗻𝗱 𝗿𝗲𝗴𝗲𝗻𝗲𝗿𝗮𝘁𝗶𝗼𝗻. It may also help restore immune balance in certain inflammatory and autoimmune conditions.

ARA-290 is also being explored for its role in supporting 𝘁𝗶𝘀𝘀𝘂𝗲 𝗿𝗲𝗰𝗼𝘃𝗲𝗿𝘆 𝗮𝗻𝗱 𝗺𝗲𝘁𝗮𝗯𝗼𝗹𝗶𝗰 𝗵𝗲𝗮𝗹𝘁𝗵, including improvements in lipid and glucose metabolism in individuals with metabolic conditions such as Type 2 diabetes.','["https://rtsnxmatvbabdylsnuuh.supabase.co/storage/v1/object/public/menu-images/1773320478037-1gbzrivq38x.png"]'::jsonb,10,'active','{"category":"all","srcId":"41c5a929-b6e9-46e8-8ca8-ef1170ea79fe","purity":"99.00","storage":"Store at -20°C"}'::jsonb);
INSERT INTO products (id,"tenantId",sku,slug,name,"priceCents",currency,description,images,stock,status,metadata) VALUES ('hpglow-matrixyl-topical-use-only','hpglow','MATRIXYLTOPICALU','matrixyl-topical-use-only','Matrixyl (Topical Use Only)',129900,'PHP','𝗠𝗮𝘁𝗿𝗶𝘅𝘆𝗹 is a well-known peptide used in advanced skincare to help support the skin’s natural collagen production. By encouraging the production of collagen, elastin, and other structural proteins, 𝗶𝘁 𝗵𝗲𝗹𝗽𝘀 𝗶𝗺𝗽𝗿𝗼𝘃𝗲 𝘀𝗸𝗶𝗻 𝗳𝗶𝗿𝗺𝗻𝗲𝘀𝘀, 𝗲𝗹𝗮𝘀𝘁𝗶𝗰𝗶𝘁𝘆, 𝗮𝗻𝗱 𝗼𝘃𝗲𝗿𝗮𝗹𝗹 𝘁𝗲𝘅𝘁𝘂𝗿𝗲.

With consistent topical use, Matrixyl may help 𝗿𝗲𝗱𝘂𝗰𝗲 𝘁𝗵𝗲 𝗮𝗽𝗽𝗲𝗮𝗿𝗮𝗻𝗰𝗲 𝗼𝗳 𝗳𝗶𝗻𝗲 𝗹𝗶𝗻𝗲𝘀 𝗮𝗻𝗱 𝘄𝗿𝗶𝗻𝗸𝗹𝗲𝘀 while supporting smoother, more hydrated, and healthier-looking skin. It works with the skin’s natural renewal process, making it a 𝗽𝗼𝗽𝘂𝗹𝗮𝗿 𝗶𝗻𝗴𝗿𝗲𝗱𝗶𝗲𝗻𝘁 𝗶𝗻 𝗺𝗼𝗱𝗲𝗿𝗻 𝗮𝗻𝘁𝗶-𝗮𝗴𝗶𝗻𝗴 𝘀𝗸𝗶𝗻𝗰𝗮𝗿𝗲 𝗳𝗼𝗿𝗺𝘂𝗹𝗮𝘁𝗶𝗼𝗻𝘀.','["https://rtsnxmatvbabdylsnuuh.supabase.co/storage/v1/object/public/menu-images/1773319531314-x9dkkb5g82a.png"]'::jsonb,5,'active','{"category":"topicals-and-serums","srcId":"5b705760-c4e3-4a39-93ab-40e7e7af187a","purity":"99.00","featured":true,"discountEnabled":true,"discountPrice":899}'::jsonb);
INSERT INTO products (id,"tenantId",sku,slug,name,"priceCents",currency,description,images,stock,status,metadata) VALUES ('hpglow-lumicopper-ghk-cu-topical-set','hpglow','LUMICOPPERGHKCUT','lumicopper-ghk-cu-topical-set','LumiCopper: GHK-CU Topical Set',189900,'PHP','𝗚𝗛𝗞-𝗖𝘂 𝗧𝗼𝗽𝗶𝗰𝗮𝗹 is a next-generation copper peptide recognized in cosmetic science for its ability to 𝘀𝘂𝗽𝗽𝗼𝗿𝘁 𝗵𝗲𝗮𝗹𝘁𝗵𝗶𝗲𝗿-𝗹𝗼𝗼𝗸𝗶𝗻𝗴, 𝗺𝗼𝗿𝗲 𝗿𝗲𝘀𝗶𝗹𝗶𝗲𝗻𝘁 𝘀𝗸𝗶𝗻. Known for encouraging 𝗰𝗼𝗹𝗹𝗮𝗴𝗲𝗻 𝘀𝘂𝗽𝗽𝗼𝗿𝘁 and 𝗶𝗺𝗽𝗿𝗼𝘃𝗶𝗻𝗴 𝘁𝗵𝗲 𝗮𝗽𝗽𝗲𝗮𝗿𝗮𝗻𝗰𝗲 𝗼𝗳 𝘀𝗸𝗶𝗻 𝗳𝗶𝗿𝗺𝗻𝗲𝘀𝘀, this peptide helps refine the look of fine lines while promoting a smoother, more refreshed complexion.

Designed to work in synergy with a hyaluronic acid carrier, GHK-Cu helps maintain hydration balance while supporting skin renewal pathways linked to elasticity and overall skin quality. Over time, skin appears more supple, refined, and visibly revitalized.

FOR TOPICAL USE ONLY.','["https://rtsnxmatvbabdylsnuuh.supabase.co/storage/v1/object/public/menu-images/1770964880430-lutuoq1av9s.png"]'::jsonb,4,'active','{"category":"topicals-and-serums","srcId":"9af17675-838b-4c51-b808-ee67cd8124b6","purity":"99.00","storage":"Store at -20°C","freeShipping":true,"inclusions":["[Torriden Dive In Low Molecular Hyaluronic Acid Serum 50ml","GHK-CU Topical 1g","2pcs Saline Water 5ml","2pcs 3cc Syringe","10 Alcohol Pads","1/8tsp Measuring Spoon","Small Ceramic Bowl","Small Silicone Mixer]"]}'::jsonb);
