INSERT INTO products (id,"tenantId",sku,slug,name,"priceCents",currency,description,images,stock,status,metadata) VALUES ('hpglow-5-amino-1mq','hpglow','5AMINO1MQ','5-amino-1mq','5-Amino-1MQ',198900,'PHP','𝟱-𝗔𝗺𝗶𝗻𝗼-𝟭𝗠𝗤 is a metabolic-support compound designed to 𝗵𝗲𝗹𝗽 𝗶𝗺𝗽𝗿𝗼𝘃𝗲 𝗯𝗼𝗱𝘆 𝗰𝗼𝗺𝗽𝗼𝘀𝗶𝘁𝗶𝗼𝗻 𝗮𝗻𝗱 𝗲𝗻𝗲𝗿𝗴𝘆 𝗺𝗲𝘁𝗮𝗯𝗼𝗹𝗶𝘀𝗺. By inhibiting the NNMT enzyme, it helps preserve NAD⁺ levels, supporting mitochondrial function, fat metabolism, and cellular energy production.

This compound is widely explored for its potential to 𝗽𝗿𝗼𝗺𝗼𝘁𝗲 𝗳𝗮𝘁 𝗹𝗼𝘀𝘀 𝘄𝗵𝗶𝗹𝗲 𝗵𝗲𝗹𝗽𝗶𝗻𝗴 𝗽𝗿𝗲𝘀𝗲𝗿𝘃𝗲 𝗹𝗲𝗮𝗻 𝗺𝘂𝘀𝗰𝗹𝗲 𝗺𝗮𝘀𝘀. It may also support insulin sensitivity, metabolic efficiency, and overall cellular health.

Because of its role in improving metabolic activity and mitochondrial function, 𝟱-𝗔𝗺𝗶𝗻𝗼-𝟭𝗠𝗤 𝗵𝗮𝘀 𝗴𝗮𝗶𝗻𝗲𝗱 𝗮𝘁𝘁𝗲𝗻𝘁𝗶𝗼𝗻 𝗶𝗻 𝗳𝗮𝘁 𝗹𝗼𝘀𝘀, 𝗺𝗲𝘁𝗮𝗯𝗼𝗹𝗶𝗰 𝗵𝗲𝗮𝗹𝘁𝗵, 𝗮𝗻𝗱 𝗹𝗼𝗻𝗴𝗲𝘃𝗶𝘁𝘆-𝗳𝗼𝗰𝘂𝘀𝗲𝗱 𝗽𝗿𝗼𝘁𝗼𝗰𝗼𝗹𝘀.','["https://rtsnxmatvbabdylsnuuh.supabase.co/storage/v1/object/public/menu-images/1773320940821-8d34xwq3dvk.png"]'::jsonb,1,'active','{"category":"all","srcId":"75f4bd87-0a39-45a3-b5e9-ae2353225576","purity":"99.00","storage":"Store at -20°C"}'::jsonb);
INSERT INTO products (id,"tenantId",sku,slug,name,"priceCents",currency,description,images,stock,status,metadata) VALUES ('hpglow-smooth8-reset-snap-8-topical-set','hpglow','SMOOTH8RESETSNAP','smooth8-reset-snap-8-topical-set','Smooth8 Reset (Snap-8 Topical Set)',179900,'PHP','“𝗕𝗼𝘁𝗼𝘅-𝗜𝗻𝘀𝗽𝗶𝗿𝗲𝗱 𝗥𝗲𝘀𝘂𝗹𝘁𝘀. 𝗡𝗼 𝗡𝗲𝗲𝗱𝗹𝗲𝘀.”

Meet 𝗦𝗡𝗔𝗣-𝟴, the advanced neuro-peptide often called “𝗕𝗼𝘁𝗼𝘅 𝗶𝗻 𝗮 𝗕𝗼𝘁𝘁𝗹𝗲” in the skincare world. Designed for topical use, this next-generation peptide helps 𝘀𝗼𝗳𝘁𝗲𝗻 𝘁𝗵𝗲 𝗹𝗼𝗼𝗸 𝗼𝗳 𝗲𝘅𝗽𝗿𝗲𝘀𝘀𝗶𝗼𝗻 𝗹𝗶𝗻𝗲𝘀 by targeting the same surface pathways associated with repetitive facial movements — without injections, downtime, or stiffness. SNAP-8 is a refined version of Argireline, formulated to 𝗵𝗲𝗹𝗽 𝘃𝗶𝘀𝗶𝗯𝗹𝘆 𝘀𝗺𝗼𝗼𝘁𝗵 𝗳𝗶𝗻𝗲 𝗹𝗶𝗻𝗲𝘀 𝗮𝗻𝗱 𝘄𝗿𝗶𝗻𝗸𝗹𝗲𝘀 over time. When used consistently, it supports a more relaxed, refreshed, and youthful appearance, especially in high-movement areas like the forehead, crow’s feet, and smile lines.','["https://rtsnxmatvbabdylsnuuh.supabase.co/storage/v1/object/public/menu-images/1770965100162-tnvb0tujk6i.png"]'::jsonb,2,'active','{"category":"topicals-and-serums","srcId":"0eeef65d-051a-467c-ac3b-9c60014eab15","purity":"99.00","freeShipping":true,"inclusions":["[𝗜𝗻𝗰𝗹𝘂𝘀𝗶𝗼𝗻𝘀:","Good Molecules Hyaluronic Acid Serum","Snap-8","Phosphate Buffered Saline","2pcs 3ml Disposable Syringe","10pcs Alcohol Pads]"]}'::jsonb);
