INSERT INTO products (id,"tenantId",sku,slug,name,"priceCents",currency,description,images,stock,status,metadata) VALUES ('hpglow-aqualyx','hpglow','AQUALYX','aqualyx','Aqualyx ',350000,'PHP','Aqualyx (Cosmetic Grade) is a premium, non-surgical fat-dissolving solution designed to precisely target stubborn localized fat. Favoured by leading aesthetic professionals, it delivers refined contouring and visibly smoother results without surgery. Targets stubborn, localized fat, Non-surgical body contouring solution, Precision treatment for refined shaping, Gradual, natural-looking results, Trusted by aesthetic professionals worldwide. Common treatment areas include the chin, jawline, abdomen, flanks, thighs, and knees.

